// Une la respuesta de Claude con la oferta original y filtra por score
const cfg = $('Config').first().json;
const original = $('Preparar scoring').item.json;
let ev = { score: 0, razones: ["respuesta no parseable"], linea: "OTRO", propuesta: "" };
try {
  let raw = $json.content[0].text.trim().replace(/^```(json)?\s*/,"").replace(/\s*```$/,"");
  ev = JSON.parse(raw);
} catch (e) {}
if ((ev.score || 0) < cfg.scoreMinimo) return null;  // descarta silenciosamente
const { payload, ...oferta } = original;
return { json: { ...oferta, ...ev } };

// Construye el payload para la API de Anthropic (un item por oferta)
const cfg = $('Config').first().json;
const j = $json;
const prompt = "Eres mi filtro de oportunidades freelance. Mi perfil real y verificable: " + cfg.perfil +
  "\n\nIMPORTANTE: en la propuesta NUNCA inventes nombres de clientes, cantidades de proyectos entregados, metricas de resultados, ni ningun detalle que no este escrito tal cual en mi perfil de arriba. Si ninguna credencial encaja perfecto, usa la mas cercana de mi perfil, sin agregar detalles inventados." +
  "\n\nEvalúa esta oferta y responde SOLO con JSON válido, sin bloques de código:\n" +
  '{"score": 0-10, "razones": ["max 3, concretas"], "linea": "DOCS|N8N|SISTEMA|FOOD|OTRO", ' +
  '"propuesta": "borrador de propuesta de max 130 palabras en el idioma de la oferta: ' +
  '(1) primera linea reflejando SU problema especifico, (2) solucion en 2-3 pasos con mi stack, ' +
  '(3) UNA credencial real, tal cual esta en mi perfil arriba, sin inventar detalles adicionales, (4) pregunta especifica de cierre. Sin Dear sir, sin adulacion."}' +
  "\n\nOFERTA [" + j.fuente + "] " + j.titulo +
  " | Presupuesto: $" + (j.presupuesto_monto != null ? j.presupuesto_monto : "?") + " USD (" + j.presupuesto_tipo + ")" +
  (j.presupuesto_monto_original != null && j.presupuesto_moneda_original && j.presupuesto_moneda_original !== "USD" ? " [originalmente " + j.presupuesto_monto_original + " " + j.presupuesto_moneda_original + "]" : "") +
  (j.ofertas != null ? " | Competencia: " + j.ofertas + " ofertas ya recibidas" + (j.oferta_promedio != null ? " (promedio " + j.oferta_promedio + " " + (j.presupuesto_moneda_original || "USD") + ")" : "") : "") +
  "\n" + j.descripcion;
return { json: { ...j, payload: {
  model: cfg.anthropicModel,
  max_tokens: 800,
  messages: [{ role: "user", content: prompt }]
}}};

// Filtro duro + deduplicación persistente (solo en ejecuciones de producción)
const cfg = $('Config').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.vistos = staticData.vistos || {};
// Limpieza: conserva máximo 3000 ids para que no crezca sin límite
const keys = Object.keys(staticData.vistos);
if (keys.length > 3000) { for (const k of keys.slice(0, keys.length - 3000)) delete staticData.vistos[k]; }

const out = [];
for (const item of items) {
  const j = item.json;
  const texto = ((j.titulo || "") + " " + (j.descripcion || "")).toLowerCase();
  if (staticData.vistos[j.id]) continue;
  if (!j.sinFiltroPalabras && !cfg.keywordsIncluir.some(k => texto.includes(k.toLowerCase()))) { staticData.vistos[j.id] = 1; continue; }
  if (cfg.keywordsExcluir.some(k => texto.includes(k.toLowerCase()))) { staticData.vistos[j.id] = 1; continue; }
  const m = j.presupuesto_monto;
  if (m !== null && m !== undefined) {
    const min = j.presupuesto_tipo === "hora" ? cfg.presupuestoMinimoHora : cfg.presupuestoMinimoFijo;
    if (m < min) { staticData.vistos[j.id] = 1; continue; }
  }
  if (cfg.maxOfertas && j.ofertas != null && j.ofertas > cfg.maxOfertas) { staticData.vistos[j.id] = 1; continue; }
  staticData.vistos[j.id] = 1;
  out.push(item);
}
return out;

// Normaliza la respuesta de Freelancer.com API y convierte el presupuesto a USD
const out = [];
const res = items[0].json;
const projects = res.result && res.result.projects ? res.result.projects : [];

const tasasRespaldo = { USD: 1, INR: 83, PKR: 278, BDT: 110, PHP: 56, NGN: 1550, EUR: 0.92, GBP: 0.79, AUD: 1.52, CAD: 1.36, ZAR: 18.3, IDR: 15800 };
let tasas = tasasRespaldo;
try {
  const tasasRes = await this.helpers.httpRequest({ url: "https://open.er-api.com/v6/latest/USD", json: true });
  if (tasasRes && tasasRes.rates) tasas = tasasRes.rates;
} catch (e) {}

for (const p of projects) {
  const b = p.budget || {};
  const monedaCodigo = (p.currency && (p.currency.code || p.currency.sign)) || "USD";
  const montoOriginal = (b.minimum !== undefined && b.minimum !== null) ? b.minimum : null;
  let montoUSD = montoOriginal;
  let monedaTexto = monedaCodigo;
  if (montoOriginal !== null && monedaCodigo !== "USD") {
    const tasa = tasas[monedaCodigo];
    if (tasa) {
      montoUSD = Math.round((montoOriginal / tasa) * 100) / 100;
    } else {
      monedaTexto = monedaCodigo + " (no reconocida, sin convertir)";
    }
  }
  out.push({ json: {
    id: "freelancer_" + p.id,
    fuente: "Freelancer",
    titulo: p.title || "",
    descripcion: (p.preview_description || p.description || "").slice(0, 1500),
    presupuesto_tipo: (p.type === "hourly") ? "hora" : "fijo",
    presupuesto_monto: montoUSD,
    presupuesto_monto_original: montoOriginal,
    presupuesto_moneda_original: monedaTexto,
    url: "https://www.freelancer.com/projects/" + (p.seo_url || p.id),
    fecha: p.time_submitted ? new Date(p.time_submitted * 1000).toISOString() : "",
    ofertas: (p.bid_stats && p.bid_stats.bid_count != null) ? p.bid_stats.bid_count : null,
    oferta_promedio: (p.bid_stats && p.bid_stats.bid_avg != null) ? Math.round(p.bid_stats.bid_avg) : null
  }});
}
return out;

// Normaliza items de RemoteOK (cada item es una oferta; el primero es metadata legal)
const out = [];
for (const item of items) {
  const j = item.json;
  if (!j || !j.position) continue;
  const tags = (j.tags || []).join(" ").toLowerCase();
  out.push({ json: {
    id: "remoteok_" + j.id,
    fuente: "RemoteOK",
    titulo: j.position + " @ " + (j.company || "?"),
    descripcion: ((j.description || "").replace(/<[^>]+>/g, " ").slice(0, 1500)) + " | tags: " + tags,
    presupuesto_tipo: "hora",
    presupuesto_monto: j.salary_min ? Math.round(j.salary_min / 2080) : null,
    url: j.url || ("https://remoteok.com/l/" + j.id),
    fecha: j.date || ""
  }});
}
return out;

// ═══════ CONFIGURACIÓN — edita SOLO este nodo ═══════
const CONFIG = {
  // Correo donde quieres recibir las ofertas encontradas
  correoDestino: "you@example.com",
  correoOrigen: "you@example.com",

  // Claude API (opcional pero recomendado). Vacío = sin scoring, llegan todas las filtradas.
  anthropicApiKey: "EN_CREDENCIAL_N8N", // la clave real vive en la credencial "Anthropic - x-api-key" del nodo Claude API; dejar este texto no vacío para activar el scoring
  anthropicModel: "claude-haiku-4-5",
  scoreMinimo: 7,

  // Freelancer.com API (opcional). Token gratis en freelancer.com/api. Vacío = solo RemoteOK.
  freelancerToken: "EN_CREDENCIAL_N8N", // el token real vive en la credencial "Freelancer - oauth token" del nodo Freelancer API; dejar este texto no vacío para activar la rama de Freelancer
  freelancerQuery: "n8n OR automation OR \"data extraction\" OR scraping OR \"api integration\"",

  // Filtro duro
  keywordsIncluir: ["n8n","automation","automatizacion","automatización","python","scraping",
    "api integration","integración","invoice","factura","pdf","ocr","extraction","extracción",
    "claude","workflow","make.com","zapier","inventory","inventario","winforms","c#",
    "recipe","restaurant","excel","next.js","nextjs","react","typescript","react native",
    "expo","dashboard","admin panel","kyc","identity verification","marketplace","full stack"],
  keywordsExcluir: ["wordpress theme","logo","video edit","academic","homework","game",
    "blockchain token","only $5","data entry manual"],
  presupuestoMinimoFijo: 100,     // USD
  presupuestoMinimoHora: 15,      // USD/h
  maxOfertas: 100,                 // descartar publicaciones que ya tengan más ofertas que esto (solo Freelancer)

  // Perfil para el scoring de Claude
  perfil: "Desarrollador de automatización: stack n8n autoalojado en producción (buscador de oportunidades con scoring por IA + evaluador anti-estafa de mensajes de Fiverr, ambos funcionando ahora mismo). " +
    "Extracción de datos de documentos con IA: demo publicada en GitHub (invoice-extractor-demo) que usa la API de Claude para leer facturas/PDFs y exportarlos a datos estructurados. " +
    "Desarrollo y mantengo Sistemagestion, un sistema de gestión (ERP) a medida en C#/.NET 8 con SQLite para una empresa de manufactura: producción diaria con control de materiales y desperdicio, bonos de producción, nómina con cumplimiento de la LOTTT venezolana y tasa USD/BCV, libros fiscales de IVA (SENIAT), cuentas por pagar, análisis de punto de equilibrio. " +
    "Español nativo, inglés escrito. " +
    "NO hago: diseño gráfico, temas WordPress, video, data entry manual."
};
return [{ json: CONFIG }];

const out = [];
for (const item of items) {
  const text = item.json.textPlain || item.json.text || "";
  if (!text) continue;

  const idMatch = text.match(/\/jobs\/~(\d+)/);
  if (!idMatch) continue;
  const jobId = idMatch[1];
  const url = `https://www.upwork.com/jobs/~${jobId}`;

  let titulo = (item.json.subject || "").replace(/^New job alert:\s*/i, "").trim();
  if (!titulo) {
    const titleMatch = text.match(/\n\n([^\n]+?):\s*https:\/\/www\.upwork\.com\/jobs\/~\d+\?link=title/);
    titulo = titleMatch ? titleMatch[1].trim() : "";
  }
  titulo = titulo.replace(/\.\.\.$/, "").trim();

  const budgetMatch = text.match(/(Fixed|Hourly):\s*\$([\d.,]+)(?:\s*[-\u2013]\s*\$?([\d.,]+))?/i);
  let presupuesto_tipo = "fijo";
  let presupuesto_monto = null;
  if (budgetMatch) {
    presupuesto_tipo = /hourly/i.test(budgetMatch[1]) ? "hora" : "fijo";
    const low = parseFloat(budgetMatch[2].replace(/,/g, ""));
    const high = budgetMatch[3] ? parseFloat(budgetMatch[3].replace(/,/g, "")) : null;
    presupuesto_monto = high ? (low + high) / 2 : low;
  }

  let descripcion = "";
  const descMatch = text.match(/Posted[^\n]*\n\n([\s\S]+?)\s*(?:\.\.\. more:|more:)/);
  if (descMatch) descripcion = descMatch[1].replace(/\s+/g, " ").trim();
  const clientMatch = text.match(/(Payment verified[^\n]*)\n/);
  if (clientMatch) descripcion += " | Cliente: " + clientMatch[1].trim();

  if (!titulo || presupuesto_monto === null) continue;

  out.push({
    json: {
      id: "upwork-" + jobId,
      fuente: "Upwork",
      titulo,
      descripcion,
      presupuesto_tipo,
      presupuesto_monto,
      url,
      fecha: new Date().toISOString().slice(0, 10)
    }
  });
}
return out;

// Normaliza las vacantes de Work Remoto (WordPress REST, tipo "empleo", categoría Desarrollo)
// Son EMPLEOS en relación de dependencia, no proyectos freelance: se marcan para que el filtro
// de palabras clave no las descarte y para que Claude las evalúe como vacante de empleo.
const limpiar = (s) => String(s || "")
  .replace(/<br\s*\/?>/gi, "\n").replace(/<\/(p|li|h\d|div)>/gi, "\n")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&#8211;/g, "–").replace(/&#8217;/g, "'")
  .replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">")
  .replace(/[ \t]+/g, " ").replace(/\n\s*\n+/g, "\n").trim();

const out = [];
for (const item of items) {
  const e = item.json;
  if (!e || !e.id) continue;
  const m = e.meta || {};
  const titulo = limpiar(e.title && e.title.rendered).replace(/\s*[–-]\s*Remoto\s*$/i, "").trim();
  const cuerpo = limpiar(e.content && e.content.rendered).slice(0, 1500);
  const salMin = parseFloat(m._empleo_salario_min) || 0;
  const salMax = parseFloat(m._empleo_salario_max) || 0;
  const moneda = m._empleo_moneda || "USD";
  const pais = m._empleo_pais || "no indicado";
  const cabecera =
    "[VACANTE DE EMPLEO REMOTO en relación de dependencia. SÍ me interesa el empleo remoto fijo: NO restes puntos " +
    "por no ser freelance ni por ser tiempo completo. Puntúa solo por encaje técnico con mi perfil, condiciones y " +
    "elegibilidad de país. Resido en Venezuela: si los países elegibles no incluyen Venezuela ni una mención general a " +
    "Latinoamérica, puntúa 4 o menos y dilo en las razones. En \"propuesta\" escribe un mensaje breve de postulación.]\n" +
    "Empresa: " + (m._empleo_empresa || "no indicada") + "\n" +
    "Países elegibles: " + pais + "\n" +
    "Jornada: " + (m._empleo_jornada || "no indicada") + "\n" +
    "Salario publicado: " + (salMin > 0 ? salMin + (salMax > salMin ? " - " + salMax : "") + " " + moneda : "no indicado") + "\n" +
    "Vence: " + (m._empleo_expira || "no indicado") + "\n" +
    "Cómo postular: " + (m._empleo_postular_url || "ver enlace de la oferta") + "\n\n";
  out.push({ json: {
    id: "workremoto_" + e.id,
    fuente: "Work Remoto (empleo)",
    titulo: titulo,
    descripcion: cabecera + cuerpo,
    presupuesto_tipo: "mensual",
    presupuesto_monto: salMin > 0 ? salMin : null,
    presupuesto_monto_original: salMin > 0 ? salMin : null,
    presupuesto_moneda_original: moneda,
    url: e.link,
    url_postulacion: m._empleo_postular_url || "",
    fecha: e.date_gmt ? e.date_gmt + "Z" : "",
    ofertas: null,
    oferta_promedio: null,
    sinFiltroPalabras: true
  }});
}
return out;
